import json
# Simplified, illustrative Zimbabwe outline + main roads + towns (lon, lat). Not survey-grade.
outline=[(25.26,-17.79),(25.85,-17.92),(26.5,-17.93),(27.3,-17.95),(27.9,-17.1),(28.76,-16.52),(28.85,-16.03),(29.4,-15.7),(30.42,-15.64),(31.0,-16.0),(31.6,-16.6),(32.3,-16.9),(32.87,-16.97),(33.0,-17.4),(32.98,-18.0),(32.7,-18.7),(32.9,-19.4),(33.05,-19.8),(32.6,-20.4),(32.5,-21.3),(31.3,-22.4),(30.0,-22.3),(29.37,-22.18),(28.9,-21.6),(27.6,-21.05),(26.7,-20.5),(26.2,-19.5),(25.25,-19.0),(25.26,-17.79)]
T={"Harare":(31.05,-17.83),"Bulawayo":(28.58,-20.15),"Mutare":(32.67,-18.97),"Gweru":(29.81,-19.45),"Kwekwe":(29.81,-18.92),"Kadoma":(29.91,-18.33),"Chegutu":(30.14,-18.13),"Masvingo":(30.83,-20.07),"Chinhoyi":(30.20,-17.36),"Karoi":(29.69,-16.81),"Kariba":(28.80,-16.52),"Chirundu":(28.85,-16.03),"Bindura":(31.33,-17.30),"Marondera":(31.55,-18.19),"Rusape":(32.13,-18.53),"Chivhu":(30.88,-19.02),"Beitbridge":(30.00,-22.22),"Hwange":(26.50,-18.37),"Victoria Falls":(25.83,-17.93),"Mt Darwin":(31.58,-16.77),"Zvishavane":(30.06,-20.33),"Chipinge":(32.62,-20.19)}
R=[("A5",["Harare","Chegutu","Kadoma","Kwekwe","Gweru","Bulawayo"]),("A8",["Bulawayo","Hwange","Victoria Falls"]),("A3",["Harare","Marondera","Rusape","Mutare"]),("A4",["Harare","Chivhu","Masvingo","Beitbridge"]),("A1",["Harare","Chinhoyi","Karoi","Chirundu"]),("A2",["Harare","Bindura","Mt Darwin"]),("A9",["Gweru","Zvishavane","Masvingo"]),("A10",["Masvingo","Chipinge"]),("R1",["Karoi","Kariba"])]
f=[{"type":"Feature","properties":{"kind":"country","name":"Zimbabwe"},"geometry":{"type":"Polygon","coordinates":[[list(p) for p in outline]]}}]
for n,ts in R: f.append({"type":"Feature","properties":{"kind":"road","name":n},"geometry":{"type":"LineString","coordinates":[list(T[t]) for t in ts]}})
for n,(lo,la) in T.items(): f.append({"type":"Feature","properties":{"kind":"town","name":n},"geometry":{"type":"Point","coordinates":[lo,la]}})
json.dump({"type":"FeatureCollection","features":f},open("assets/geojson/basemap.json","w"),separators=(",",":"))
